from pathlib import Path
import json,numpy as np,pandas as pd
P=Path(__file__).resolve().parent;root=P.parent;k=json.load(open(P/'assign.json'));d=pd.read_csv(root/'outputs/chain_amino_acid_mean_RSA.csv',keep_default_na=False,float_precision='round_trip');a=d.pivot(index=['pdb','chain'],columns='aa',values='mean_RSA').reindex(columns=list('ARNDCQEGHILKMFPSTWYV'));labels=np.array([k[(p+c).lower()]['k'] for p,c in a.index]);keep=np.isin(labels,['euk','prok']);a=a[keep];labels=labels[keep];a.to_csv(P/'classified_chain_mean_RSA.csv');pd.DataFrame({'pdb':[i[0] for i in a.index],'chain':[i[1] for i in a.index],'kingdom':labels}).to_csv(P/'classified_chain_labels.csv',index=False);A=a.values;valid=np.isfinite(A).astype(float);Y=np.nan_to_num(A);S=Y.sum(0);N=valid.sum(0);mask=labels=='euk';obs=np.nanmean(A[mask],0)-np.nanmean(A[~mask],0);mean=obs.mean();t=mean/obs.std(ddof=1)*np.sqrt(20);R={'n_chains':len(A),'n_euk':int(mask.sum()),'n_prok':int((~mask).sum()),'observed_mean_RSA_difference':float(mean),'observed_AA_t':float(t),'observed_positive_AA_count':int((obs>0).sum()),'observed_shifts':dict(zip(a.columns,obs.tolist()))};rng=np.random.default_rng(20261006);allD={};B=100000
for name,nA in [('half_split',len(A)//2),('original_sizes',int(mask.sum()))]:
 blocks=[]
 for start in range(0,B,200):
  W=np.zeros((min(200,B-start),len(A)))
  for row in W:row[rng.permutation(len(A))[:nA]]=1
  s=W@Y;n=W@valid;blocks.append(s/n-(S-s)/(N-n))
 D=np.concatenate(blocks);allD[name]=D;signs=(D>0).sum(1);means=D.mean(1);tt=means/D.std(1,ddof=1)*np.sqrt(20);r={'replicates':B,'group_sizes':[nA,len(A)-nA],'all_same_sign_count':int(((signs==0)|(signs==20)).sum()),'P_all_same_sign':float(np.mean((signs==0)|(signs==20))),'P_at_least19_same':float(np.mean((signs<=1)|(signs>=19))),'per_AA_positive_probability_range':[float(np.min(np.mean(D>0,0))),float(np.max(np.mean(D>0,0)))],'mean_shift_extreme_count':int((abs(means)>=abs(mean)).sum()),'t_extreme_count':int((abs(tt)>=abs(t)).sum()),'p_mean_shift_plus_one':float((1+(abs(means)>=abs(mean)).sum())/(B+1)),'p_t_plus_one':float((1+(abs(tt)>=abs(t)).sum())/(B+1)),'mean_shift_null_025_50_975':np.quantile(means,[.025,.5,.975]).tolist(),'positive_sign_count_histogram':np.bincount(signs,minlength=21).tolist()};R[name]=r;print(name,json.dumps(r),flush=True)
R['seed']=20261006;R['independent_P_all_same_sign']=2/2**20;R['limitations']=['The original classification rules are preserved with quote-aware CSV parsing; taxonomy assignments were not independently revalidated.','Randomization tests the pooled-chain exchangeability null, not kingdom causality after conditioning on all protein context.','Mean-RSA statistic is not PCA coordinate shift; it follows the requested mean-RSA test.','No exceedances among 100000 draws means Monte Carlo resolution approximately 1e-5; approximate 95% upper confidence bound for underlying tail probability is 3e-5, not p=0.']
(P/'results.json').write_text(json.dumps(R,indent=2));np.savez_compressed(P/'null_shifts.npz',**allD);print('OBSERVED',json.dumps({k:v for k,v in R.items() if k.startswith('observed')}),flush=True)
